CREATE TABLE employees (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,employee_code VARCHAR(30) NOT NULL,name VARCHAR(190) NOT NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_employees_code(employee_code),UNIQUE KEY uq_employees_email(email),KEY idx_employees_active(is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
